// SPDX-License-Identifier: MIT
// CPPM output generated by the RMT peripheral: the whole frame is handed to the hardware
// as a list of symbols, so timing does not depend on interrupt latency or task scheduling.
#pragma once

#include <atomic>
#include <cstdint>

#include "driver/rmt_tx.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "rc/config.hpp"
#include "rc/pulse_pack.hpp"

namespace app {

class ConfigStore;
class InputHub;

class CppmOutput {
public:
    CppmOutput(ConfigStore& config, InputHub& hub);

    /// Configure the RMT channel and start the frame task. Returns false when disabled or on error.
    bool start();

    bool running() const { return task_ != nullptr; }
    uint32_t framesSent() const { return frames_sent_; }

private:
    static void taskEntry(void* arg);
    static bool onTransDone(rmt_channel_handle_t chan, const rmt_tx_done_event_data_t* edata, void* ctx);
    void run();
    bool queueFrame(const rc::Frame& frame, const rc::cppm::Config& wave);

    ConfigStore& config_;
    InputHub& hub_;
    rc::CppmConfig cfg_{};
    rmt_channel_handle_t channel_ = nullptr;
    rmt_encoder_handle_t encoder_ = nullptr;
    TaskHandle_t task_ = nullptr;

    /// Two frame buffers: one may be transmitting while the other is queued.
    static constexpr std::size_t kBuffers = 2;
    rmt_symbol_word_t buffers_[kBuffers][rc::pulse::kMaxSymbols]{};
    std::size_t next_buffer_ = 0;
    std::size_t in_flight_ = 0;
    std::atomic<uint32_t> frames_sent_{0};
};

}  // namespace app
